        assertEquals((17 * 37 + obj[0].hashCode()) * 37, new HashCodeBuilder(17, 37).append((Object) obj).toHashCode());
        obj[1] = new Object();
        assertEquals((17 * 37 + obj[0].hashCode())* 37 + obj[1].hashCode(),new HashCodeBuilder(17,37).append((Object)obj).toHashCode());
    }

